import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry tanh_kernel(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u32 size
)
{
    .reg .u64 %rd<18>;
    .reg .u32 %r<14>;
    .reg .f32 %f<18>;
    .reg .pred %p<4>;
    ld.param.u64 %rd1, [input_ptr];
    ld.param.u64 %rd2, [output_ptr];
    ld.param.u32 %r1, [size];
    cvta.to.global.u64 %rd3, %rd1;
    cvta.to.global.u64 %rd4, %rd2;
    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %ntid.x;
    mov.u32 %r4, %tid.x;
    mad.lo.s32 %r11, %r2, %r3, %r4;
    mov.u32 %r5, %r11;
    mov.u32 %r6, %nctaid.x;
    mul.lo.s32 %r7, %r6, %r3;
    shr.u32 %r8, %r1, 4;
    mul.wide.s32 %rd5, %r11, 64;
    add.s64 %rd6, %rd3, %rd5;
    add.s64 %rd7, %rd4, %rd5;
    mul.wide.s32 %rd11, %r7, 64;
vecloop:
    setp.ge.s32 %p1, %r5, %r8;
    @%p1 bra vecdone;
    ld.global.nc.v4.f32 {%f1, %f2, %f3, %f4}, [%rd6];
    add.s64 %rd12, %rd6, 16;
    ld.global.nc.v4.f32 {%f5, %f6, %f7, %f8}, [%rd12];
    add.s64 %rd13, %rd6, 32;
    ld.global.nc.v4.f32 {%f9, %f10, %f11, %f12}, [%rd13];
    add.s64 %rd14, %rd6, 48;
    ld.global.nc.v4.f32 {%f13, %f14, %f15, %f16}, [%rd14];
    tanh.approx.f32 %f1, %f1;
    tanh.approx.f32 %f2, %f2;
    tanh.approx.f32 %f3, %f3;
    tanh.approx.f32 %f4, %f4;
    tanh.approx.f32 %f5, %f5;
    tanh.approx.f32 %f6, %f6;
    tanh.approx.f32 %f7, %f7;
    tanh.approx.f32 %f8, %f8;
    tanh.approx.f32 %f9, %f9;
    tanh.approx.f32 %f10, %f10;
    tanh.approx.f32 %f11, %f11;
    tanh.approx.f32 %f12, %f12;
    tanh.approx.f32 %f13, %f13;
    tanh.approx.f32 %f14, %f14;
    tanh.approx.f32 %f15, %f15;
    tanh.approx.f32 %f16, %f16;
    st.global.cs.v4.f32 [%rd7], {%f1, %f2, %f3, %f4};
    add.s64 %rd15, %rd7, 16;
    st.global.cs.v4.f32 [%rd15], {%f5, %f6, %f7, %f8};
    add.s64 %rd16, %rd7, 32;
    st.global.cs.v4.f32 [%rd16], {%f9, %f10, %f11, %f12};
    add.s64 %rd17, %rd7, 48;
    st.global.cs.v4.f32 [%rd17], {%f13, %f14, %f15, %f16};
    add.s32 %r5, %r5, %r7;
    add.s64 %rd6, %rd6, %rd11;
    add.s64 %rd7, %rd7, %rd11;
    bra vecloop;
vecdone:
    mul.lo.s32 %r9, %r8, 16;
    add.s32 %r10, %r11, %r9;
tailloop:
    setp.ge.s32 %p2, %r10, %r1;
    @%p2 bra done;
    mul.wide.s32 %rd8, %r10, 4;
    add.s64 %rd9, %rd3, %rd8;
    add.s64 %rd10, %rd4, %rd8;
    ld.global.nc.f32 %f17, [%rd9];
    tanh.approx.f32 %f17, %f17;
    st.global.cs.f32 [%rd10], %f17;
    add.s32 %r10, %r10, %r7;
    bra tailloop;
done:
    ret;
