        sm_count = device_props.multi_processor_count
        blocks_per_sm = 32
        grid_x = max(1, min(full_grid_x, sm_count * blocks_per_sm))
        module = _get_ptx_module()
        module.launch(
            "tanh_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x_contig, output, i32(size)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )

        return output.view(x.shape)

